import { describe, expect, test } from 'vitest';
import { base64, caught } from '../proto/screen-test-utils';
import { concat, enc, u8 } from '../proto/test-utils';
import { loadScreenDictionary } from './screen-dictionary';
import { ZstdScreenDecoder, ZstdScreenDecoderError } from './zstd-decoder';

// Independent zstd CLI -3 --no-check output, not generated by this decoder.
const compressedScreenFixture = u8(
  0x28, 0xb5, 0x2f, 0xfd, 0x00, 0x58, 0x0d, 0x01, 0x00, 0xc8, 0x4d, 0x61,
  0x63, 0x56, 0x69, 0x65, 0x77, 0x65, 0x72, 0x20, 0x73, 0x63, 0x72, 0x65,
  0x65, 0x6e, 0x20, 0x66, 0x69, 0x78, 0x74, 0x75, 0x72, 0x65, 0x0a, 0x01,
  0x00, 0xa1, 0x86, 0xfd, 0x39, 0x06,
);

function zstdError(fn: () => unknown): ZstdScreenDecoderError {
  const error = caught(fn);
  expect(error).toBeInstanceOf(ZstdScreenDecoderError);
  return error as ZstdScreenDecoderError;
}

// Ported from ZstdScreenDecoderTests.swift.
describe('ZstdScreenDecoder (ZstdScreenDecoderTests.swift)', () => {
  test('zstdScreenFixtureAtEveryFragmentBoundary', async () => {
    const expected = enc('MacViewer screen fixture\n'.repeat(100));
    for (let split = 0; split <= compressedScreenFixture.length; split++) {
      const decoder = await ZstdScreenDecoder.create();
      const decoded = concat(
        decoder.append(compressedScreenFixture.slice(0, split)),
        decoder.append(compressedScreenFixture.slice(split)),
      );
      decoder.finish();
      expect(decoded).toEqual(expected);
      expect(decoder.hasIncompleteFrame).toBe(false);
      decoder.dispose();
    }
  });

  test('zstdRejectsTruncationAndLimitsExpansionAcrossChunks', async () => {
    const truncated = await ZstdScreenDecoder.create();
    truncated.append(compressedScreenFixture.slice(0, -1));
    expect(zstdError(() => truncated.finish()).code).toBe('incompleteFrame');
    const bounded = await ZstdScreenDecoder.create(null, 100);
    expect(
      zstdError(() => {
        for (const byte of compressedScreenFixture) bounded.append(u8(byte));
      }).code,
    ).toBe('outputLimitExceeded');
    expect(zstdError(() => bounded.append(u8(1))).code).toBe('resetRequired');
    bounded.reset();
    // A manually encoded standard raw block: one three-byte frame containing ABC.
    const rawFrame = u8(0x28, 0xb5, 0x2f, 0xfd, 0x20, 0x03, 0x19, 0, 0, 65, 66, 67);
    expect(bounded.append(rawFrame)).toEqual(enc('ABC'));
    bounded.finish();
  });

  test('zstdConcatenatedFramesAndCorruption', async () => {
    const decoder = await ZstdScreenDecoder.create(null, 6000);
    expect(decoder.append(concat(compressedScreenFixture, compressedScreenFixture)).length).toBe(5000);
    decoder.finish();
    decoder.reset();
    expect(zstdError(() => decoder.append(enc('invalid compressed frame'))).code).toBe('invalidData');
  });

  test('trainedScreenDictionarySurvivesMissionReset', async () => {
    // Independent zstd CLI -3 -D 8bit.dat output, with dictionary ID 3da0bd10.
    const compressed = base64('KLUv/QdYEL2gPS0BAOhNYWNWaWV3ZXIgZGljdGlvbmFyeSBmaXh0dXJlCgEA0Qz4ygnbOEGJ');
    const expected = enc('MacViewer dictionary fixture\n'.repeat(100));
    const missingDictionary = await ZstdScreenDecoder.create();
    const mismatch = zstdError(() => missingDictionary.append(compressed));
    expect(mismatch.code).toBe('invalidData');
    expect(mismatch.detail).toBe('Dictionary mismatch');
    const decoder = await ZstdScreenDecoder.create(await loadScreenDictionary());
    for (let round = 0; round < 2; round++) {
      const chunks: Uint8Array[] = [];
      for (const byte of compressed) chunks.push(decoder.append(u8(byte)));
      decoder.finish();
      expect(concat(...chunks)).toEqual(expected);
      decoder.reset();
    }
  });
});

describe('ZstdScreenDecoder (web port additions)', () => {
  // Frame header without single-segment flag, so the Window_Descriptor byte
  // (exponent = windowLog - 10, in the top five bits) sets the window size.
  // One final raw block carries "ABC".
  const windowFrame = (windowLog: number) =>
    u8(0x28, 0xb5, 0x2f, 0xfd, 0x00, (windowLog - 10) << 3, 0x19, 0, 0, 65, 66, 67);

  test('accepts a 2^27 window and rejects a window above 2^27 (windowLogMax 27)', async () => {
    const decoder = await ZstdScreenDecoder.create();
    expect(decoder.append(windowFrame(27))).toEqual(enc('ABC'));
    decoder.finish();
    decoder.reset();
    const error = zstdError(() => decoder.append(windowFrame(28)));
    expect(error.code).toBe('invalidData');
    expect(error.detail).toBe('Frame requires too much memory for decoding');
    decoder.dispose();
  });

  test('empty input returns empty output without starting a frame', async () => {
    const decoder = await ZstdScreenDecoder.create();
    expect(decoder.append(new Uint8Array())).toEqual(new Uint8Array());
    expect(decoder.hasIncompleteFrame).toBe(false);
    decoder.finish();
    decoder.dispose();
  });

  test('a disposed decoder cannot be used', async () => {
    const decoder = await ZstdScreenDecoder.create();
    decoder.dispose();
    decoder.dispose(); // idempotent
    expect(() => decoder.append(u8(1))).toThrow(/disposed/);
    expect(() => decoder.reset()).toThrow(/disposed/);
  });

  test('rejects a non-positive output limit', async () => {
    await expect(ZstdScreenDecoder.create(null, 0)).rejects.toThrow(RangeError);
  });
});
